#include <linux/uaccess.h>

int snd_seq_remove_events(struct snd_seq_client *client, void __user *arg) {
    struct {
        unsigned int mode;
    } info;

    if (copy_from_user(&info, arg, sizeof(info)))
        return -EFAULT;

    if (info.mode & SND_SEQ_REMOVE_INPUT) {
        if (client->type == SNDRV_SEQ_CLIENT_TYPE_USER)
            snd_seq_fifo_clear(&client->input);
    }

    if (info.mode & SND_SEQ_REMOVE_OUTPUT)
        snd_seq_client_remove_cells(client, client->output.queue);

    return 0;
}

int snd_seq_remove_events(struct snd_seq_client *client, void __user *arg)
{
	struct snd_seq_remove_mode mode;
	int result;

	result = copy_from_user(&mode, arg, sizeof(mode));
	if (result)
		return -EFAULT;

	if (mode.flags & SNDRV_SEQ_REMOVE_INPUT) {
		if (client->type == SNDRV_SEQ_CLIENT_TYPE_USER)
			snd_seq_fifo_clear(&client->input_queue);
	}

	if (mode.flags & SNDRV_SEQ_REMOVE_OUTPUT) {
		struct snd_seq_cell *cell;
		while ((cell = snd_seq_cell_get(&client->output_queue)) != NULL)
			snd_seq_cell_free(cell);
	}

	return 0;
}

int snd_seq_remove_events(struct snd_seq_client *client, void __user *arg)
{
    struct {
        int mode;
    } info;

    if (copy_from_user(&info, arg, sizeof(info)))
        return -EFAULT;

    if (info.mode & SNDRV_SEQ_REMOVE_INPUT) {
        if (client->type == SNDRV_SEQ_CLIENT_TYPE_USER)
            snd_seq_fifo_clear(client->input_pool);
    }

    if (info.mode & SNDRV_SEQ_REMOVE_OUTPUT)
        snd_seq_remove_output(client);

    return 0;
}
